var arenaRune2 = new THREE.Mesh(new THREE.TorusGeometry(3.3, 0.018, 4, 40), arenaRuneMat.clone());
arenaRune2.rotation.x = Math.PI / 2;
arenaRune2.position.y = 0.15;
