var dueling = false;

/* Sombra del héroe */
var heroShadow = makeBlob(1.9);
hubGroup.add(heroShadow);
var heroAvatar = null;
var heroHolder = new THREE.Group();
hubGroup.add(heroHolder);
var avatarRenderTarget = null;
var arenaHeroShadow = makeBlob(1.9);
arenaHeroShadow.visible = false;
