  var recommendRing = new THREE.Mesh(new THREE.TorusGeometry(boss ? .7 : .55, .018, 5, 36), new THREE.MeshBasicMaterial({ color: color('#e4c07a'), transparent: true, opacity: .7, depthWrite: false }));
