/* -------------------------------------------------------------------------
   API V2
   ------------------------------------------------------------------------- */
V2.heroes = {
  boot: v2hBoot,
  mount: v2hMount,
  unmount: v2hUnmount,
  update: v2hUpdate,
  open: v2hOpen,
  close: v2hClose
};

