    g.strokeStyle = '#E4C07A';
    g.beginPath();
    g.moveTo(13, 14);
    g.lineTo(180, 14);
    g.lineTo(180, 185);
    g.lineTo(96.5, 156);
    g.lineTo(13, 185);
    g.stroke();
    g.globalAlpha = 1;

    v2aDrawMotif(g, meta.motif, 100, 94, 42, '#F7F3E8', 5);

    /* Colgantes de las dos puntas del vuelo. */
    g.fillStyle = '#E4C07A';
    g.fillRect(18, 184, 8, 44);
    g.fillRect(164, 184, 8, 44);
    g.fillStyle = '#C9A35F';
    g.beginPath();
    g.arc(22, 234, 6, 0, Math.PI * 2);
    g.fill();
    g.beginPath();
    g.arc(168, 234, 6, 0, Math.PI * 2);
    g.fill();

