      veg.instanceMatrix.needsUpdate = true;
      veg.castShadow = false;
      veg.receiveShadow = false;
      veg.name = 'v2-map-veg-' + (islandCfg && islandCfg.order ? islandCfg.order : 'x');
      v2aMarkDecorative(veg);
      group.add(veg);
