var v2wWorldRoot = null;
var v2wDummy = null;
var v2wThreeOk = false;
var v2wChestBodyMesh = null;
var v2wChestLids = [];
var v2wGuideBodyMesh = null;
var v2wGuideAccentMesh = null;
var v2wTelescopeGroup = null;
