    v2smState.filter = 'all';
    v2smState.clickHandler = function (event) { v2smOnClick(event); };
    v2smState.keyHandler = function (event) { v2smOnKeydown(event); };
    v2smState.docKeyHandler = function (event) { v2smOnDocKeydown(event); };
