            groups: av && av.cosmetics ? av.cosmetics.groups.length : 0,
            slots: av && av.cosmetics ? JSON.parse(JSON.stringify(av.cosmetics.slots || {})) : {},
            title: av && av.cosmetics ? av.cosmetics.title || null : null,
