    av.head.rotation.y = Math.sin(time * 0.55) * 0.025 + 0.1;
    av.leftArm.rotation.z = 0.04 + Math.sin(time * 0.8) * 0.012;
    av.rightArm.rotation.z = -0.04 - Math.sin(time * 0.8) * 0.012;
    animateAvatarCosmetics(av, dt, time, false, 0);
