    stars += '<button type="button" class="v23tutStar" data-action="tutorial-goto" data-step="' + s + '" ' +
      'aria-label="Ir al paso ' + (s + 1) + ' de 5: ' + esc(slides[s].kicker) + '" title="' + esc(slides[s].kicker) + '">' +
      '<i aria-hidden="true">✦</i><span>' + (s + 1) + '</span></button>';
