  document.body.classList.add('v23tutOpen');
  try { initAudio(); } catch (e) {}
  v23wSfx();
  try {
    window.dispatchEvent(new CustomEvent('v23b:tutorial-opened', { detail: { step: 0 } }));
  } catch (e) {}
